    #include "sort_merge.h"

    static void merge(TYPE a[SIZE], TYPE temp[SIZE], int start, int m, int stop) {
        // Copy left half [start, m-1] to temp
        for (int i = start; i < m; i++) {
            temp[i] = a[i];
        }
        // Copy right half [m, stop-1] to temp
        for (int i = m; i < stop; i++) {
            temp[i] = a[i];
        }
        // Merge the two halves
        int i = start, j = m;
        for (int k = start; k < stop; k++) {
            if (j >= stop || (i < m && temp[i] <= temp[j])) {
                a[k] = temp[i];
                i++;
            } else {
                a[k] = temp[j];
                j++;
            }
        }
    }

    void ms_mergesort(TYPE a[SIZE]) {
        TYPE temp[SIZE];
        // Iterative merge sort
        for (int width = 1; width < SIZE; width *= 2) {
            for (int i = 0; i < SIZE; i += 2 * width) {
                int mid = i + width;
                if (mid >= SIZE) {
                    break;
                }
                int end = i + 2 * width;
                if (end > SIZE) {
                    end = SIZE;
                }
                merge(a, temp, i, mid, end);
            }
        }
    }

